local runtime_key = '__outlaw_aetheryx_runtime_v6_icon_clean'
local previous_runtime = rawget(_G, runtime_key)
local __outlaw_aetheryx_runtime
if type(previous_runtime) == 'table' and type(previous_runtime.events) == 'table' then
for _, event in pairs(previous_runtime.events) do
event.list = { }
event.items = { }
end
previous_runtime.generation = (previous_runtime.generation or 0) + 1
__outlaw_aetheryx_runtime = previous_runtime
else
__outlaw_aetheryx_runtime = { events = { }, generation = 1 }
rawset(_G, runtime_key, __outlaw_aetheryx_runtime)
end
do
local function now()
return globals.realtime()
end
local function report(event_name, err)
client.error_log(string.format(
'[aetheryx] %s callback error: %s',
tostring(event_name), tostring(err)
))
end
function __outlaw_aetheryx_runtime.dispatch(event_name, ...)
local event = __outlaw_aetheryx_runtime.events[event_name]
if event == nil then
return
end
local time = now()
local list = event.list
for i = 1, #list do
local item = list[i]
if item.active and time >= item.retry_at then
local ok, err = pcall(item.callback, ...)
if ok then
item.retry_at = 0
else
item.retry_at = time + 1
if time >= item.report_at then
item.report_at = time + 5
report(event_name, err)
end
end
end
end
end
function __outlaw_aetheryx_runtime.set(event_name, callback)
if type(event_name) ~= 'string' or type(callback) ~= 'function' then
return
end
local event = __outlaw_aetheryx_runtime.events[event_name]
if event == nil then
event = {
list = { },
items = { },
registered = false
}
__outlaw_aetheryx_runtime.events[event_name] = event
end
local item = event.items[callback]
if item == nil then
item = {
callback = callback,
active = true,
retry_at = 0,
report_at = 0
}
event.items[callback] = item
event.list[#event.list + 1] = item
else
item.active = true
item.retry_at = 0
end
if not event.registered then
event.registered = true
client.set_event_callback(event_name, function(...)
__outlaw_aetheryx_runtime.dispatch(event_name, ...)
end)
end
end
function __outlaw_aetheryx_runtime.unset(event_name, callback)
local event = __outlaw_aetheryx_runtime.events[event_name]
if event == nil then
return
end
local item = event.items[callback]
if item ~= nil then
item.active = false
end
end
end
function __outlaw_aetheryx_runtime.delay(delay, callback, ...)
local args = { ... }
local count = select('#', ...)
client.delay_call(delay, function()
local ok, err = pcall(callback, unpack(args, 1, count))
if not ok then
client.error_log('[outlaw] delay_call: '..tostring(err))
end
end)
end

-- Managed direct callbacks: avoid duplicate anonymous handlers after script reloads.
-- Keep this separate from the main runtime dispatcher because some callbacks are
-- intentionally registered directly and need their original event arguments.
local direct_callback_registry_key = '__outlaw_aetheryx_direct_callbacks_v1'
local previous_direct_callbacks = rawget(_G, direct_callback_registry_key)
if type(previous_direct_callbacks) == 'table' then
    for event_name, callbacks in pairs(previous_direct_callbacks) do
        if type(callbacks) == 'table' then
            for i = 1, #callbacks do
                local callback = callbacks[i]
                if type(callback) == 'function' then
                    pcall(client.unset_event_callback, event_name, callback)
                end
            end
        end
    end
end
local direct_callback_registry = {}
rawset(_G, direct_callback_registry_key, direct_callback_registry)
local function set_managed_event_callback(event_name, callback)
    client.set_event_callback(event_name, callback)
    local callbacks = direct_callback_registry[event_name]
    if callbacks == nil then
        callbacks = {}
        direct_callback_registry[event_name] = callbacks
    end
    callbacks[#callbacks + 1] = callback
end
