local color = { } do
color = ffi.typeof [[
        struct {
            unsigned char r;
            unsigned char g;
            unsigned char b;
            unsigned char a;
        }
    ]]
local M = { } do
M.__index = M
function M:__tostring()
return string.format(
'%i, %i, %i, %i',
self:unpack()
)
end
function M.lerp(a, b, t)
return color(
a.r + t * (b.r - a.r),
a.g + t * (b.g - a.g),
a.b + t * (b.b - a.b),
a.a + t * (b.a - a.a)
)
end
function M:unpack()
return self.r, self.g, self.b, self.a
end
function M:clone()
return color(self:unpack())
end
function M:to_hex()
return string.format(
'%02x%02x%02x%02x',
self:unpack()
)
