local function pretty_builder_state_name(state)
local map = {
['Shared'] = 'Global',
['Slow Walk'] = 'Walking',
['Crouching'] = 'Duck',
['Crouching & Move'] = 'Duck Move',
['Air & Crouched'] = 'Air Duck',
['Legit AA'] = 'Legit'
}
return map[state] or state
end
local function builder_team_key(value)
return (value == 'Counter-Terrorist' or value == 'CT') and 'CT' or 'T'
end
local function get_builder_header()
local state_name = pretty_builder_state_name(current_state)
if current_state == 'Freestanding' then
return string.format(
'Customize  \a%s~\a%s  %s',
lock_clr(), reference.get_color(true), state_name
)
end
return string.format(
'Customize  \a%s~\a%s  %s  \a%s·\a%s  %s',
lock_clr(), reference.get_color(true), state_name,
lock_clr(), reference.get_color(true), active_builder_team
)
end
 
builder.physical = {
angles = create_builder_items('UI'),
anti_bruteforce = create_anti_bruteforce_items('UI'),
defensive = create_defensive_items('UI'),
}

builder.profile_open = false
builder.state_label = menu.new(ui.new_label, 'AA', 'Anti-aimbot angles', new_key('Customize condition', 'builder_header'))
builder.state = aetheryx_native_inline.create(
{ w = 125, h = 18, x = 120, anchor_item = builder.physical.angles.enabled, same_line = true },
ui.new_combobox, 'AA', 'Anti-aimbot angles', new_key('\n', 'builder_condition'), {
'Global', 'Stand', 'Move', 'Slow walk', 'Duck', 'Duck move', 'Air', 'Air duck', 'Freestanding', 'Legit'
}
)
 
do
local aliases = {
['Shared']='Global', ['Standing']='Stand', ['Moving']='Move', ['Slow Walk']='Slow walk',
['Crouching']='Duck', ['Crouching & Move']='Duck move', ['Air']='Air',
['Air & Crouched']='Air duck', ['Freestanding']='Freestanding', ['Legit AA']='Legit'
}
local canonical = {}
for key, value in pairs(aliases) do canonical[value]=key end
local raw_get, raw_set = builder.state.get, builder.state.set
function builder.state:get()
local value = raw_get(self)
return canonical[value] or value
end
function builder.state:set(value)
return raw_set(self, aliases[value] or value)
end
end
builder.state:set('Standing')
builder.profile_gear = aetheryx_native_inline.create(
{ w = 18, h = 18, anchor_item = builder.state, anchor_right = true, gap = 11,
same_line = true, native_type = 2,
