local thresholds={
 scout={air={perfect=.007,worst=.080},land={perfect=.003,worst=.035},noscope={perfect=.040,worst=.120}},
 awp={air={perfect=.010,worst=.100},land={perfect=.001,worst=.025},noscope={perfect=.030,worst=.100}},
