 deagle={air={perfect=.020,worst=.150},land={perfect=.004,worst=.050},noscope={perfect=.004,worst=.050}},
 revolver={air={perfect=.015,worst=.120},land={perfect=.003,worst=.040},noscope={perfect=.003,worst=.040}},
 pistol={air={perfect=.020,worst=.120},land={perfect=.005,worst=.045},noscope={perfect=.005,worst=.045}}}
local weapon_types={[40]='scout',[9]='awp',[38]='auto',[11]='auto',[1]='deagle',[64]='revolver',
 [2]='pistol',[3]='pistol',[4]='pistol',[30]='pistol',[32]='pistol',[36]='pistol',[61]='pistol',[63]='pistol'}
local profiles={scout={'SSG 08','SSG08','Scout','SSG-08'},awp={'AWP'},
 auto={'G3SG1 / SCAR-20','Auto Snipers','AutoSnipers'},deagle={'Desert Eagle','Deagle'},
 revolver={'R8 Revolver','Revolver'},pistol={'Pistols'}}
local saved,profile_cache={},{}
local selected_weapons={}
local active,blocked=false,false
local last_weapon,last_index,last_command,last_tick=nil,nil,nil,nil
local delay_ticks=0
local function finite(v)return type(v)=='number'and v==v and v~=math.huge and v~=-math.huge end
local function bounded(v,a,b)return math.max(a,math.min(b,v))end
local function with_profile(profile,fn)
 if not selector then return false end
 local previous=ui.get(selector)
 local ok,result=pcall(function()
 if previous~=profile then ui.set(selector,profile)end
 if ui.get(selector)~=profile then return false end
 return fn()
 end)
 local restored=pcall(function()if ui.get(selector)~=previous then ui.set(selector,previous)end end)
 return ok and result==true and restored
end
local function release()
 active=false
 for profile,item in pairs(saved)do
 local ok=with_profile(profile,function()
 -- Do not erase an edit made by the user or another module after our last write.
 if ui.get(hc_ref)==item.applied then ui.set(hc_ref,item.original)end
 return true
 end)
 if ok then saved[profile]=nil end
 end
end
local function reset()
 release();blocked=false;last_weapon=nil;last_index=nil;last_command=nil;last_tick=nil;delay_ticks=0
end
local function resolve_profile(kind)
 if profile_cache[kind]then return profile_cache[kind]end
 for _,profile in ipairs(profiles[kind]or {})do
 if with_profile(profile,function()return true end)then profile_cache[kind]=profile;return profile end
 end
end
local function compute_hc(kind,base,minimum,lp,weapon,scoped)
 local t=scoped and thresholds[kind].land or thresholds[kind].noscope
 local penalty=entity.get_prop(weapon,'m_fAccuracyPenalty')
 if not finite(penalty)then return nil end
 local fire=bounded(1-(penalty-t.perfect)/(t.worst-t.perfect),0,1)
 local vx,vy=entity.get_prop(lp,'m_vecVelocity')
 if not finite(vx)or not finite(vy)then return nil end
 local speed=math.sqrt(vx*vx+vy*vy)
 local speed_fraction=speed<=2 and 1 or speed>=85 and 0 or 1-(speed-2)/83
 local accuracy=math.min(fire,speed_fraction)
 accuracy=accuracy*accuracy*(3-2*accuracy)
 local target=minimum==-1 and math.floor(15+40*(1-accuracy))or minimum
 return bounded(math.floor(target+(base-target)*(1-accuracy)+.5),1,100)
end
local function update(cmd)
 if not ref.enabled:get()then reset();return end
 if not ref.hotkey:get()then release();blocked=false;last_command=nil;return end
 local lp=entity.get_local_player()
 if not lp or not entity.is_alive(lp)or not selector then reset();return end
 local weapon=entity.get_player_weapon(lp)
 if not weapon then reset();return end
 local index=entity.get_prop(weapon,'m_iItemDefinitionIndex')
 if not finite(index)then reset();return end
 index=bit.band(index,0xFFFF)
 local kind=weapon_types[index]
 if not kind or not selected_weapons[kind]then reset();return end
 local tick=globals.tickcount()
 if finite(last_tick)and tick<last_tick then reset()end
 last_tick=tick
 if weapon~=last_weapon or index~=last_index then
 release();last_weapon=weapon;last_index=index;delay_ticks=8;last_command=cmd and cmd.command_number or tick;blocked=false;return
 end
 -- Aesthetic is ground-only. Always release the HC lease when entering air.
 local flags=entity.get_prop(lp,'m_fFlags')
 if not finite(flags)or bit.band(flags,1)==0 then release();blocked=true;return end
 local command=cmd and cmd.command_number
 if not finite(command)then command=tick end
 if command==last_command then return end
 last_command=command
 if delay_ticks>0 then delay_ticks=delay_ticks-1;release();blocked=false;return end
 local profile=resolve_profile(kind)
 if not profile then release();blocked=true;return end
 local minimum=ref.hitchance:get()
 if not finite(minimum)then release();blocked=true;return end
 local scoped=entity.get_prop(lp,'m_bIsScoped')
 scoped=scoped==1 or scoped==true
 local applied=with_profile(profile,function()
 local current=ui.get(hc_ref)
 if not finite(current)then return false end
 local item=saved[profile]
 -- The formula must use the original HC, never the previous calculated override.
 local base=item and current==item.applied and item.original or current
 local value=compute_hc(kind,base,minimum,lp,weapon,scoped)
 if not value then return false end
 if not item then item={};saved[profile]=item end
 item.original=base
 if current~=value then ui.set(hc_ref,value)end
 item.applied=value
 return ui.get(hc_ref)==value
 end)
 active=applied;blocked=not applied
 if not applied then release()end
end
local last_error=-math.huge
local function protected_update(cmd)
 local ok,err=pcall(update,cmd)
 if not ok then
 pcall(reset)
 local now=globals.realtime()
 if now<last_error or now-last_error>=3 then
 client.error_log('[aetheryx] Force shot: '..tostring(err));last_error=now
 end
 end
end
local function refresh_weapons()
 selected_weapons={}
 for _,name in ipairs(ref.weapons:get()or {})do selected_weapons[tostring(name):lower()]=true end
 reset()
end
local function paint()
 if not ref.enabled:get()or not ref.hotkey:get()or not ref.indicator:get()then return end
 local lp=entity.get_local_player();if not lp or not entity.is_alive(lp)then return end
 if blocked then renderer.indicator(255,0,0,255,'FORCE SHOT')
 elseif active then renderer.indicator(233,255,0,255,'FORCE SHOT')end
end
ref.enabled:set_callback(reset)
ref.hotkey:set_callback(function()if not ref.hotkey:get()then release();blocked=false;last_command=nil end end)
ref.weapons:set_callback(refresh_weapons)
ref.hitchance:set_callback(release)
refresh_weapons()
__outlaw_aetheryx_runtime.set('setup_command',protected_update)
__outlaw_aetheryx_runtime.set('paint',paint)
__outlaw_aetheryx_runtime.set('round_prestart',reset)
__outlaw_aetheryx_runtime.set('level_init',reset)
__outlaw_aetheryx_runtime.set('shutdown',reset)
__outlaw_aetheryx_runtime.set('pre_config_save',release)
__outlaw_aetheryx_runtime.set('pre_config_load',reset)
__outlaw_aetheryx_runtime.set('post_config_load',refresh_weapons)

port.force_shot_owns=function() return active end
port.block_legacy_write=function(ref) return ref==hc_ref and active end
end

port.menu=menu_elements
port.config=config_system
port.defaults=bridge.defaults
port.exploit=exploit
port.runtime=aa_runtime_state
local function publish_state()
 local state=port.state
 local names={Shared='Global',['Slow Walk']='Slowwalk',Crouching='Crouching T',['Crouching & Move']='Crouching T',['Air & Crouched']='Crouch-Air',['Legit AA']='Using'}
 state.condition=names[aa_runtime_state.aa_state] or aa_runtime_state.aa_state or 'Global'
 local dir=aa_runtime_state.manual_direction
 state.manual_yaw=dir=='left' and -75 or dir=='right' and 100 or dir=='forward' and 180 or 0
 state.inverter=localplayer.body_yaw<0
 state.is_defensive_active=aa_runtime_state.aa_owner=='Defensive'
end
__outlaw_aetheryx_runtime.set('setup_command',publish_state)
if first_run and bridge.defaults[1] then
 local ok,err=config_system.import(bridge.defaults[1].data)
 if not ok then error('Outlaw default conversion: '..tostring(err)) end
end
if bridge.legacy_ui.set_port_visible then bridge.legacy_ui.set_port_visible(menu_elements.category_selector.current()=='misc') end
port.legacy_controls={manual_yaw={selection={get=function()return menu_elements.antiaim.features.manual_yaw.checkbox:get() and 'Static' or 'Disabled' end}},freestanding={selection={get=function()return menu_elements.antiaim.features.freestanding.checkbox:get() and 'Default' or 'Disabled' end}}}
return port
end

